head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF70016";
scwin.todayDd = "";         // 서버 현재일 (yyyyMMdd) — 원본 cGetToday("yyyymmdd")(클라이언트 날짜)
scwin.jobTitl = "";         // 직책 (03: 담당자, 그 외: 팀장) — 원본 js_jobtitl
scwin.depCd = "";           // 부서코드 (ZSYS: 시스템관리자 → 재마감처리 버튼 보임) — 원본 js_dep_cd
scwin.procJob = "";         // 진행 중인 처리명 (완료·실패 메시지 인자) — 원본 procJob
scwin.TAB_PROC = 0;         // [마감처리] 탭 (원본 MaxTab_01 ActiveIndex 1)
scwin.TAB_SEARCH = 1;       // [마감처리내역] 탭 (원본 ActiveIndex 2)
scwin.JOBTITL_CHRG = "03";  // 직책코드 — 담당자
scwin.DEP_CD_SYS = "ZSYS";  // 부서코드 — 시스템관리자
// 원본 : /lstproc/ULDSTF70016.gfm (신종증권 신규상장 마감처리 / 마감처리내역, 1270×750 메인 화면 — 화면명 「(탭)마감처리」 는 탭 2개를 가진 화면이라는 뜻)
/*
 * 화면 동작
 *  - [마감처리] 탭: 마감일(당일 고정)의 다음 영업일(상장일)에 상장하는 신종증권 신규상장 마감대상을 보여 주고,
 *    담당자 확인 → 팀장승인 순서로 마감한다. 시스템관리자(ZSYS)는 재마감처리(이전 마감기록 삭제)를 할 수 있다.
 *  - [마감처리내역] 탭: 고른 마감일의 송신데이터(마감처리내역)를 조회한다.
 *  - 통신·데이터 정의는 ULDSTF70016_API.md 명세 기준(cls-procs 5종). 조회 한 번에 상장일·마감이력·목록이 함께 온다.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF70016/ULDSTF70016.md (§번호는 이 문서의 절)
 */

// 이 화면의 역할→버튼 매핑 — 담당자 확인·팀장승인 활성은 마감이력으로 정한다(§6.5). 재마감처리는 보임/숨김으로 따로 다룬다(§6.6).
scwin.BTN_MAP = {
    revw : "btn_Revw",      // [담당자 확인]
    cls : "btn_Cls"         // [팀장승인]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70016.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 세션 정보 → init 바인딩 → 버튼 초기 상태 → [마감처리] 탭 상태(마감일 = 오늘) → 조회. (원본 gform onload — §3)
 * 탭 본문은 alwaysDraw="true" 라 처음부터 그려져 있어 탭 안 버튼도 여기서 제어한다(규칙 45 예외, 선례 ULDSTF08200).
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 세션·서버 날짜 — 원본 js_jobtitl·js_dep_cd 전역, cGetToday("yyyymmdd")
    scwin.jobTitl = $c.session.getUserInfo("jobtitl") ?? "";
    scwin.depCd = $c.session.getUserInfo("depCd") ?? "";
    scwin.todayDd = $c.date.getServerDateTime("yyyyMMdd");

    // 2) init 바인딩 (전환 규칙 22·37) — 마감일 단일 달력, 조회 영역 Enter 키
    $c.date.checkCalendarFormat(edt_TASK_DD, "yyyyMMdd");
    $c.win.setEnterKeyEvent(panel_Top, scwin.btn_Search_onclick);

    // 3) 버튼 초기 상태 — 재마감처리는 시스템관리자만 보이고, 담당자 확인·팀장승인은 마감이력 조회 뒤 정한다(그 전까지 잠금)
    scwin.applyReclsButton();
    $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);

    // 4) [마감처리] 탭 상태 — 마감일 = 오늘, 읽기전용 (원본 setObjectValue(edt_TASK_DD, 오늘) + OnSelChanged(1) 처리)
    scwin.applyTabMode(scwin.TAB_PROC);

    // 5) 조회 (원본 fn_list_sync)
    await scwin.listSync();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.MaxTab_01_onchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description 탭 변경 — 탭에 맞춰 마감일 입력 상태를 바꾸고 다시 조회한다. (원본 MaxTab_01 OnSelChanged — §4, §6.1)
 * @param {String} tabId 선택한 탭 id
 * @param {Number} index 선택한 탭 순번
 * @returns
 * @hidden N
 */
scwin.MaxTab_01_onchange = async function (tabId, index) {
    try {
        scwin.applyTabMode(Number(MaxTab_01.getSelectedTabIndex()));
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70016.MaxTab_01_onchange" });
    }
};

/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 버튼 클릭(조회 영역 Enter 키 포함) — 선택한 탭 기준으로 다시 조회한다. (원본 btn_Search onclick → fn_list_sync — §5)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70016.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Recls_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 재마감처리 버튼 클릭 (시스템관리자만 보임) — 처리는 scwin.recls. (§6.3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Recls_onclick = async function (e) {
    try {
        await scwin.recls();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70016.btn_Recls_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Revw_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 담당자 확인 버튼 클릭 — 처리는 scwin.revw. (§6.3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Revw_onclick = async function (e) {
    try {
        await scwin.revw();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70016.btn_Revw_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Cls_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 팀장승인 버튼 클릭 — 처리는 scwin.cls. (§6.4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Cls_onclick = async function (e) {
    try {
        await scwin.cls();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70016.btn_Cls_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_ProcExcel_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [마감처리] 엑셀저장 버튼 클릭 — 선택한 탭의 그리드를 내려받는다. (원본 doLogSave + fn_ExcelDown, doLogSave 삭제 — §6.7)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_ProcExcel_onclick = async function (e) {
    try {
        scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70016.btn_ProcExcel_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_SearchExcel_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [마감처리내역] 엑셀저장 버튼 클릭 — 선택한 탭의 그리드를 내려받는다. (원본 doLogSave + fn_ExcelDown, doLogSave 삭제 — §6.7)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_SearchExcel_onclick = async function (e) {
    try {
        scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70016.btn_SearchExcel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.searchList
 * @author Inswave
 * @date 2026. 10. 30
 * @description [마감처리] 마감대상 목록 조회 → 상장일·마감이력 표시 → 건수 → 담당자 확인·팀장승인 버튼 상태.
 * (원본 dts_Get_ListDD·dts_Item·dts_New_Proc(listGeneral digital.newlst.select.list.condition) + OnLoadCompleted — §5.1)
 * @param {String} taskDd 마감일 (yyyyMMdd)
 * @returns
 * @hidden N
 */
scwin.searchList = async function (taskDd) {
    // 원본 Reset 은 다시 읽기 전에 비운다 — 실패해도 앞 조회 결과가 남지 않게 한다.
    scwin.clearHeader();
    dma_list.setEmptyValue();
    dlt_targetList.removeAll();
    $c.stf.fillGridHeaderTotalCnt(0, edt_New_Proc_TotalCnt);

    // 명세 target 의 dma_finalLog=body.finalLog 는 뺐다 — 마감 전이면 finalLog 가 null 이고, 공통 바인딩은 null 을 그대로 setJSON 에 넘긴다.
    // 객체가 올 때만 scwin.applyHeader 가 적재한다(§5 「명세 ↔ AS-IS 차이」).
    const sbmOptions = {
        id : "sbm_searchList",
        method : "get",
        action : "/api/listing/lstproc/digital/cls-procs/select-list",
        target : "dma_list=body, dlt_targetList=body.targetList",
        gridview : "grd_New_Proc",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { taskDd : taskDd });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    if (!result.responseJSON?.success) {
        // 마감이력과 목록이 맞지 않는 상태로 처리하지 않도록 잠근다(§8 #6).
        $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
        return;
    }

    scwin.applyHeader(dma_list.get("listDd"), result.responseJSON.body?.finalLog);
    $c.stf.fillGridHeaderTotalCnt(dlt_targetList.getRowCount(), edt_New_Proc_TotalCnt);
    scwin.applyButtonState();
};

/**
 * @method
 * @name scwin.searchLog
 * @author Inswave
 * @date 2026. 10. 30
 * @description [마감처리내역] 송신데이터 목록 조회(마감일 기준) → 상장일·마감이력 표시 → 건수.
 * (원본 dts_Get_ListDD·dts_Item·dts_New_Search(listGeneral digital.newlst.select.log.condition) + OnLoadCompleted — §5.2)
 * @param {String} taskDd 마감일 (yyyyMMdd)
 * @returns
 * @hidden N
 */
scwin.searchLog = async function (taskDd) {
    scwin.clearHeader();
    dma_log.setEmptyValue();
    dlt_sndList.removeAll();
    $c.stf.fillGridHeaderTotalCnt(0, edt_New_Search_TotalCnt);

    // 명세 target 의 dma_finalLog=body.finalLog 는 searchList 와 같은 이유로 뺐다.
    const sbmOptions = {
        id : "sbm_searchLog",
        method : "get",
        action : "/api/listing/lstproc/digital/cls-procs/select-list-log",
        target : "dma_log=body, dlt_sndList=body.sndList",
        gridview : "grd_New_ProcLog",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { taskDd : taskDd });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return;

    scwin.applyHeader(dma_log.get("listDd"), result.responseJSON.body?.finalLog);
    $c.stf.fillGridHeaderTotalCnt(dlt_sndList.getRowCount(), edt_New_Search_TotalCnt);
};

/**
 * @method
 * @name scwin.postClose
 * @author Inswave
 * @date 2026. 10. 30
 * @description 마감 처리 전송(담당자 확인·팀장승인·재마감처리 공통). 성공하면 완료 안내 후 다시 조회하고, 실패하면 실패 안내.
 * 서브미션 옵션은 부르는 쪽이 전체 경로 리터럴 action 으로 만든다(전환 규칙 38). (원본 trs_revw / trs_Cls Post + OnSuccess·OnFail — §5.3~§5.5)
 * @param {Object} sbmOptions executeDynamic 옵션 (id·method·action·mediatype)
 * @returns
 * @hidden N
 */
scwin.postClose = async function (sbmOptions) {
    // 명세 요청은 세 API 모두 { taskDd, listDd } — 원본이 보내던 CHRG_EMP_NO(세션 사번)는 없다(§10 #3).
    const requestData = {
        taskDd : dma_search.get("taskDd"),
        listDd : dma_search.get("listDd")
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀 (원본 연속 클릭 — §8 #5)

    // TODO: 명세에 응답 정의가 없어 성공은 success 로만 판정한다 — 업무 결과 코드가 있는지 확인 (§10 #4)
    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    await scwin.listSync();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.listSync
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 — 선택한 탭의 목록을 마감일 기준으로 조회한다. 조회 한 번에 상장일·마감이력도 함께 온다(원본은 상장일·마감이력을 동기로 먼저 읽음). (원본 fn_list_sync — §5)
 * @returns
 * @hidden N
 */
scwin.listSync = async function () {
    const taskDd = dma_search.get("taskDd");

    if (Number(MaxTab_01.getSelectedTabIndex()) === scwin.TAB_SEARCH) {
        await scwin.searchLog(taskDd);
    } else {
        await scwin.searchList(taskDd);
    }
};

/**
 * @method
 * @name scwin.applyTabMode
 * @author Inswave
 * @date 2026. 10. 30
 * @description 탭에 맞춰 마감일 입력 상태를 바꾼다. [마감처리]는 마감일을 오늘로 고정(읽기전용), [마감처리내역]은 입력 가능.
 * (원본 MaxTab_01 OnSelChanged 의 ReadOnly·img_TASK_DD.disabled·Text = 오늘 — §6.1)
 * @param {Number} index 탭 순번 (scwin.TAB_PROC | scwin.TAB_SEARCH)
 * @returns
 * @hidden N
 */
scwin.applyTabMode = function (index) {
    if (index === scwin.TAB_PROC) {
        dma_search.set("taskDd", scwin.todayDd);
        edt_TASK_DD.setReadOnly(true);
    } else {
        edt_TASK_DD.setReadOnly(false);
    }
};

/**
 * @method
 * @name scwin.clearHeader
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 전 상장일·마감이력(위쪽 칸)을 비운다. 원본은 dts_Get_ListDD·dts_Item 을 매번 다시 읽었다(Reset). (§5)
 * @returns
 * @hidden N
 */
scwin.clearHeader = function () {
    dma_search.set("listDd", "");
    dma_finalLog.setEmptyValue();
};

/**
 * @method
 * @name scwin.applyHeader
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 응답의 상장일·마감이력을 위쪽 칸에 넣는다. 마감이력은 마감 전이면 null 이라 객체일 때만 적재한다. (원본 bnd_LIST_DD·bnd_Item — §5)
 * @param {String} listDd 상장일 (yyyyMMdd — 마감일의 다음 영업일)
 * @param {Object} finalLog 마감이력 (마감 전이면 null)
 * @returns
 * @hidden N
 */
scwin.applyHeader = function (listDd, finalLog) {
    dma_search.set("listDd", listDd ?? "");
    if (finalLog && typeof finalLog === "object") {
        dma_finalLog.setJSON(finalLog);
    }
};

/**
 * @method
 * @name scwin.checkProcDt
 * @author Inswave
 * @date 2026. 10. 30
 * @description 마감 처리 전 확인 — 마감일이 오늘인지. 원본의 시장참가자번호 검사는 원본에서 주석 처리돼 옮기지 않는다. (원본 fn_checkProcDt — §6.2)
 * @param {String} jobNm 처리명 (안내 문구용)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.checkProcDt = async function (jobNm) {
    if (dma_search.get("taskDd") !== scwin.todayDd) {
        await $c.win.alert("[마감일]이 현재일경우만 '" + jobNm + "'를 할수 있습니다.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.recls
 * @author Inswave
 * @date 2026. 10. 30
 * @description 재마감처리 — 이전 마감처리 기록을 지운다(다시 마감처리해야 함). (원본 fn_recls + fn_trSetHeader — §6.3, §5.5)
 * @returns
 * @hidden N
 */
scwin.recls = async function () {
    scwin.procJob = "재마감처리";
    if (!await scwin.checkProcDt(scwin.procJob)) return;

    const msg = "재마감처리를 선택 하셨습니다.\n재마감처리는 이전마감처리기록을 삭제하므로\n재마감처리후 다시 마감처리를 하셔야 됩니다.\n\n재마감처리를 하시겠습니까?";
    if (!await $c.win.confirm(msg)) return;

    const sbmOptions = {
        id : "sbm_remove",
        method : "post",
        action : "/api/listing/lstproc/digital/cls-procs/remove",
        mediatype : "application/json",
        isProcessMsg : false
    };
    await scwin.postClose(sbmOptions);
};

/**
 * @method
 * @name scwin.revw
 * @author Inswave
 * @date 2026. 10. 30
 * @description 담당자 확인. (원본 fn_revw + fn_trs_revw — §6.3, §5.4)
 * @returns
 * @hidden N
 */
scwin.revw = async function () {
    scwin.procJob = "담당자 확인";
    if (!await scwin.checkProcDt(scwin.procJob)) return;

    if (!await $c.win.confirm("담당자 확인 하시겠습니까?")) return;

    const sbmOptions = {
        id : "sbm_saveRevw",
        method : "post",
        action : "/api/listing/lstproc/digital/cls-procs/save-revw",
        mediatype : "application/json",
        isProcessMsg : false
    };
    await scwin.postClose(sbmOptions);
};

/**
 * @method
 * @name scwin.cls
 * @author Inswave
 * @date 2026. 10. 30
 * @description 팀장승인(마감처리). 담당자 확인 뒤에만 할 수 있다. 원본도 마감일 확인(fn_checkProcDt)을 부르지 않는다. (원본 fn_cls + fn_trs — §6.4, §5.3)
 * @returns
 * @hidden N
 */
scwin.cls = async function () {
    if ($c.util.isEmpty(dma_finalLog.get("approvTm"))) {
        await $c.win.alert("담당자가 확인하지 않았습니다. 담당자 확인 후 마감처리를 해주십시오.");
        return;
    }

    scwin.procJob = "마감처리";

    if ($c.util.isEmpty(dma_search.get("listDd"))) {
        await $c.win.alert("[상장일]이 없습니다.");
        edt_LIST_DD.focus();
        return;
    }

    if (!await $c.win.confirm("팀장 승인 하시겠습니까?")) return;

    const sbmOptions = {
        id : "sbm_saveApprov",
        method : "post",
        action : "/api/listing/lstproc/digital/cls-procs/save-approv",
        mediatype : "application/json",
        isProcessMsg : false
    };
    await scwin.postClose(sbmOptions);
};

/**
 * @method
 * @name scwin.applyButtonState
 * @author Inswave
 * @date 2026. 10. 30
 * @description 담당자 확인·팀장승인 버튼 활성. (원본 buttonSetDis — §6.5)
 *  팀장 확인(마감) 완료 → 둘 다 잠금 / 담당자 확인 전 → [담당자 확인]만 / 담당자 확인 후 → 팀장은 [팀장승인]만, 담당자는 둘 다 잠금.
 *  재마감처리 버튼도 다시 정한다.
 * @returns
 * @hidden N
 */
scwin.applyButtonState = function () {
    const isClosed = !$c.util.isEmpty(dma_finalLog.get("bzClsTm"));
    const isReviewed = !$c.util.isEmpty(dma_finalLog.get("approvEmpNm"));
    const isChrg = (scwin.jobTitl === scwin.JOBTITL_CHRG);

    const enable = [];
    if (!isClosed) {
        if (!isReviewed) {
            enable.push("revw");
        } else if (!isChrg) {
            enable.push("cls");
        }
    }
    $c.util.setButtonState("grpBtnBox", { enable : enable }, scwin.BTN_MAP);

    scwin.applyReclsButton();
};

/**
 * @method
 * @name scwin.applyReclsButton
 * @author Inswave
 * @date 2026. 10. 30
 * @description 재마감처리 버튼 — 시스템관리자(ZSYS)만 보이고 활성, 그 밖에는 숨김. (원본 gform onload·buttonSetDis 의 showObj(btn_Recls) — §6.6)
 * @returns
 * @hidden N
 */
scwin.applyReclsButton = function () {
    if (scwin.depCd === scwin.DEP_CD_SYS) {
        btn_Recls.setDisabled(false);
        btn_Recls.show("");
    } else {
        btn_Recls.hide();
    }
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 30
 * @description 선택한 탭의 그리드를 내려받는다. 0건 안내는 공통 함수가 한다.
 * 파일명은 {menuId}_{원본 이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42). (원본 fn_ExcelDown — §6.7)
 * @returns
 * @hidden N
 */
scwin.excelDown = function () {
    const prefix = $c.win.getProgramId() + "_";
    const suffix = "_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx";

    if (Number(MaxTab_01.getSelectedTabIndex()) === scwin.TAB_SEARCH) {
        $c.data.downloadGridViewExcel(grd_New_ProcLog, { fileName : prefix + "신규상장 마감처리이력목록" + suffix });
    } else {
        $c.data.downloadGridViewExcel(grd_New_Proc, { fileName : prefix + "신규상장 마감처리목록" + suffix });
    }
};
